import { NextRequest, NextResponse } from "next/server";

export const dynamic = "force-dynamic";
const configured = process.env.NEXT_PUBLIC_THESIS_ROADMAP_ORIGIN || "http://127.0.0.1:4387";
const origin = /^http:\/\/127\.0\.0\.1:\d{2,5}$/.test(configured) ? configured : "http://127.0.0.1:4387";

async function proxy(request: NextRequest, write: boolean) {
  const host = request.headers.get("host") || "";
  if (!/^(127\.0\.0\.1|localhost):\d{2,5}$/.test(host)) {
    return NextResponse.json({ error: "Der gemeinsame Lernspeicher ist nur lokal verfügbar." }, { status: 403 });
  }
  if (write && (request.headers.get("origin") !== `http://${host}` || !request.headers.get("content-type")?.startsWith("application/json"))) {
    return NextResponse.json({ error: "Same-origin JSON required" }, { status: 403 });
  }
  try {
    const body = write ? await request.text() : undefined;
    if (body && Buffer.byteLength(body, "utf8") > 2_000_000) return NextResponse.json({ error: "Request too large" }, { status: 413 });
    const response = await fetch(`${origin}/api/progress`, {
      method: write ? "POST" : "GET", cache: "no-store", signal: AbortSignal.timeout(5000),
      headers: write ? { "Content-Type": "application/json", Origin: origin } : undefined, body,
    });
    return NextResponse.json(await response.json(), { status: response.status, headers: { "Cache-Control": "no-store" } });
  } catch {
    return NextResponse.json({ error: "Lernspeicher nicht erreichbar. Öffne OPEN-STUDY-WORKSPACE.cmd. Der Eintrag wurde nicht gespeichert." }, { status: 503 });
  }
}

export const GET = (request: NextRequest) => proxy(request, false);
export const POST = (request: NextRequest) => proxy(request, true);
